import tempfile
import threading
import tomllib
import zipfile
from pathlib import Path

from rewardkit import criteria, criterion


def _legacy_criterion(*, description: str):
    """Keep fixture-level probes callable without paying each fixture separately."""
    del description

    def decorate(func):
        return func

    return decorate

