# ----------------------------------------------------------------------- helpers
def canon(obj) -> str:
    return hashlib.sha256(json.dumps(obj, sort_keys=True, separators=(",", ":"),
                                     ensure_ascii=False).encode("utf-8")).hexdigest()


def load(workspace: Path, name: str):
    try:
        return json.loads((workspace / OUT / name).read_text(encoding="utf-8"))
    except (OSError, ValueError, RecursionError):
        return None


def stamped(obj, stamp) -> bool:
    return isinstance(obj, dict) and obj.get("run_control") == stamp["run_control"] \
        and obj.get("stage") == stamp["stage"]


def rows(obj, key):
    v = obj.get(key) if isinstance(obj, dict) else None
    return v if isinstance(v, list) and all(isinstance(x, dict) for x in v) else None


# ----------------------------------------------------------------------- projections
def p_selftest(st):
    # read is left out: a correct reader always reproduces declared (spec 2.3), so it is copyable.
    f = rows(st, "files")
    if f is None:
        return None
    return [[x.get("file_id"), x.get("role"), x.get("declared"), x.get("link")] for x in f]


def p_builds(br, fields):
    b = rows(br, "builds")
    if b is None:
        return None
    return sorted([[x.get(f) for f in fields] for x in b], key=lambda r: json.dumps(r, sort_keys=True))


def p_modules(obj, fields):
    m = rows(obj, "modules")
    if m is None:
        return None
    return [[x.get(f) for f in fields] for x in m]


def p_deps_constraints(dr):
    m = rows(dr, "modules")
    if m is None:
        return None
    out = [dr.get("cut")]
    for x in m:
        reqs = x.get("requirements")
        if not isinstance(reqs, list) or not all(isinstance(q, dict) for q in reqs):
            return None
        out.append([x.get("module"), [[q.get("package"), q.get("constraint")] for q in reqs]])
    return out


def p_deps_semver(dr):
    m = rows(dr, "modules")
    if m is None:
        return None
    out = []
    for x in m:
        reqs = x.get("requirements")
        if not isinstance(reqs, list) or not all(isinstance(q, dict) for q in reqs):
            return None
        out.append([x.get("module"), [[q.get("package"), q.get("resolved"), q.get("source")] for q in reqs]])
    return out


def p_row_order(br):
    # Only the 10.2 row order; the field projections compare rows as sorted sets.
    b = rows(br, "builds")
    if not b:
        return None
    return [b == sorted(b, key=lambda x: (x.get("commit_seq"), x.get("module"), x.get("build_key")))]


def key_sets(obj):
    # The field names an output uses: its own keys, then the key sets of every list of objects inside it.
    if not isinstance(obj, dict):
        return None
    out = [sorted(obj)]
    for k in sorted(obj):
        v = obj[k]
        if isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
            out.append([k, [list(t) for t in sorted({tuple(sorted(x)) for x in v})]])
            nested = {}
            for x in v:
                for kk, vv in x.items():
                    if isinstance(vv, list) and vv and all(isinstance(y, dict) for y in vv):
                        nested.setdefault(kk, set()).update(tuple(sorted(y)) for y in vv)
            for kk in sorted(nested):
                out.append([k, kk, [list(t) for t in sorted(nested[kk])]])
    return out


