def s1_check(workspace: Path, name: str) -> bool:
    fname, proj = PROJ[name]
    obj = load(workspace, fname)
    if not stamped(obj, S1_STAMP):
        return False
    try:
        value = proj(obj)
        return value is not None and canon(value) == DIGESTS["s1:" + name]
    except (TypeError, AttributeError, KeyError, ValueError, RecursionError):
        return False


# ----------------------------------------------------------------------- package handling
def _safe_extract(zf: zipfile.ZipFile, dest: Path) -> Path | None:
    names = zf.namelist()
    for n in names:
        p = Path(n)
        if p.is_absolute() or ".." in p.parts or "\\" in n:
            return None
    zf.extractall(dest)
    tops = {Path(n).parts[0] for n in names if Path(n).parts}
    for cand in [dest] + [dest / t for t in sorted(tops)]:
        if (cand / "pyproject.toml").is_file():
            return cand
    return None


def _as_root() -> bool:
    return hasattr(os, "geteuid") and os.geteuid() == 0


def _drop_privileges() -> list:
    if _as_root() and shutil.which("setpriv"):
        return ["setpriv", f"--reuid={AGENT_UID}", f"--regid={AGENT_UID}", "--clear-groups", "--"]
    return []


def _kill_agent_processes(pgid: int) -> None:
    # A child that called setsid() has left the process group, so also sweep every process of the agent uid.
    try:
        os.killpg(pgid, signal.SIGKILL)
    except OSError:
        pass
    for proc in Path("/proc").glob("[0-9]*"):
        try:
            status = (proc / "status").read_text()
        except OSError:
            continue
        uid = next((line.split()[1] for line in status.splitlines() if line.startswith("Uid:")), None)
        if uid == str(AGENT_UID):
            try:
                os.kill(int(proc.name), signal.SIGKILL)
            except OSError:
                pass


def _run(cmd, cwd, env, timeout=RUN_TIMEOUT):
    try:
        p = subprocess.Popen(_drop_privileges() + cmd, cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
    except OSError:
        return -1
    try:
        return p.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        return -1
    finally:
        _kill_agent_processes(p.pid)
        p.wait()
        _sweep_agent_files()


def _sweep_agent_files() -> None:
    # What one run leaves in the shared writable directories must not reach the next run.
    if not _as_root():
        return
    for base in SHARED_WRITABLE:
        try:
            entries = list(Path(base).iterdir())
        except OSError:
            continue
        for entry in entries:
            try:
                if entry.lstat().st_uid != AGENT_UID:
                    continue
                if entry.is_dir() and not entry.is_symlink():
                    shutil.rmtree(entry, ignore_errors=True)
                else:
                    entry.unlink()
            except OSError:
                pass


def _set_tree(path: Path, uid: int) -> None:
    # uid owns the tree and nobody else may write to it; symlinks the agent planted are never followed.
    for root, dirs, files in os.walk(path):
        for name in [root] + [os.path.join(root, n) for n in dirs + files]:
            try:
                info = os.lstat(name)
                if stat.S_ISLNK(info.st_mode):
                    continue
                if _as_root():
                    os.lchown(name, uid, uid)
                os.chmod(name, 0o755 if stat.S_ISDIR(info.st_mode) or info.st_mode & 0o100 else 0o644)
            except OSError:
                pass


def _norm(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


def _prepare(workspace: Path) -> dict:
    with _LOCK:
        key = str(workspace)
        if key in _CACHE:
            return _CACHE[key]
        st = {"zip": False, "layout": False, "installed": False, "tests_pass": False, "runs": {}, "src": None}
        _CACHE[key] = st
        tmp = Path(tempfile.mkdtemp(prefix="ty-grade-"))
        tmp.chmod(0o755)
        st["tmp"] = tmp
        try:
            zf = zipfile.ZipFile(workspace / OUT / "package.zip")
            st["zip"] = True
            src = _safe_extract(zf, tmp / "pkg")
        except (OSError, zipfile.BadZipFile, ValueError):
            return st
        if src is None:
            return st
        st["src"] = src
        st["layout"] = (src / "src" / "trainyard" / "__init__.py").is_file() and all(
            (src / rel).is_file() and hashlib.sha256((src / rel).read_bytes()).hexdigest() == h
            for rel, h in SHIPPED_TESTS.items())
        try:
            meta = tomllib.loads((src / "pyproject.toml").read_text(encoding="utf-8"))
            deps = meta.get("project", {}).get("dependencies", [])
            names = [_norm(re.split(r"[<>=!~;\[ ]", d, maxsplit=1)[0]) for d in deps]
        except (OSError, ValueError, AttributeError, TypeError):
            return st
        if any(n not in DEP_DIRS for n in names):
            return st
        site = tmp / "site"
        env = {"PATH": ENV_PATH, "HOME": str(tmp), "LANG": "C.UTF-8",
               "PYTHONDONTWRITEBYTECODE": "1"}
        site.mkdir()
        _set_tree(tmp / "pkg", AGENT_UID)
        _set_tree(site, AGENT_UID)
        rc = _run([PYTHON, "-m", "pip", "install", "--no-deps", "--no-index", "--no-build-isolation",
                   "--no-cache-dir", "--target", str(site), str(src)], str(tmp), env)
        _set_tree(tmp / "pkg", 0)
        _set_tree(site, 0)
        if rc != 0 or not (site / "trainyard").is_dir():
            return st
        pypath = os.pathsep.join([str(site)] + [DEP_DIRS[n] for n in names])
        renv = dict(env, PYTHONPATH=pypath)
        st["env"] = renv
        if _run([PYTHON, "-S", "-c", "import trainyard"], str(tmp), renv) != 0:
            return st
        st["installed"] = True
        st["tests_pass"] = _run([PYTHON, "-S", "-m", "unittest", "discover", "-s", "tests"], str(src), renv) == 0
        # stage-2 feed, plain and renamed
        feed = tmp / "feed"
        feed.mkdir()
        with tarfile.open(fileobj=io.BytesIO(lzma.decompress(base64.b64decode(_S2_FEED_B64))), mode="r:") as tf:
            for m in tf.getmembers():
                if m.isfile() and "/" not in m.name:
                    (feed / m.name).write_bytes(tf.extractfile(m).read())
        renamed = tmp / "feed_renamed"
        renamed.mkdir()
        idx_name = None
        for p in sorted(feed.iterdir()):
            try:
                obj = json.loads(p.read_text(encoding="utf-8"))
                if isinstance(obj, dict) and obj.get("control", {}).get("role") == "index":
                    idx_name = p.name
            except (ValueError, UnicodeDecodeError):
                continue
        mapping = {}
        for i, p in enumerate(sorted(feed.iterdir())):
            mapping[p.name] = f"part_{i:03d}_{hashlib.sha256(p.name.encode()).hexdigest()[:6]}"
        for p in sorted(feed.iterdir()):
            data = p.read_bytes()
            if p.name == idx_name:
                obj = json.loads(data)
                for f in obj["files"]:
                    f["path"] = mapping.get(f["path"], f["path"])
                data = (json.dumps(obj, ensure_ascii=False, indent=1) + "\n").encode("utf-8")
            (renamed / mapping[p.name]).write_bytes(data)
        resume = tmp / "resume.json"
        try:
            shutil.copyfile(workspace / OUT / "summary.json", resume)
        except OSError:
            return st
        resume.chmod(0o644)
        _set_tree(feed, 0)
        _set_tree(renamed, 0)
        for tag, fd in (("plain", feed), ("again", feed), ("renamed", renamed)):
            out = tmp / f"out_{tag}"
            out.mkdir()
            _set_tree(out, AGENT_UID)
            rc = _run([PYTHON, "-S", "-m", "trainyard", "reconcile", "--feed", str(fd), "--resume", str(resume),
                       "--out", str(out)], str(tmp), renv)
            _set_tree(out, 0)
            got = {}
            for n in OUTPUTS:
                try:
                    got[n] = (out / n).read_bytes() if stat.S_ISREG((out / n).lstat().st_mode) else None
                except OSError:
                    got[n] = None
            st["runs"][tag] = (rc, got)
        return st


def s2_output(workspace: Path, name: str):
    # The hidden stage is graded under fresh file names (spec 2.1: file names carry no meaning), so a package
    # that finds files by name is priced here once; the runs on the original names feed only the determinism negative.
    st = _prepare(workspace)
    run = st["runs"].get("renamed")
    if not run or run[1].get(name) is None:
        return None
    try:
        return json.loads(run[1][name].decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return None


def s2_check(workspace: Path, name: str) -> bool:
    obj = s2_output(workspace, name)
    if not stamped(obj, S2_STAMP):
        return False
    if name == "selftest.json":
        files = rows(obj, "files")
        if files is None:
            return False
        obj = [sorted(obj), obj.get("opening"), [sorted(x) for x in files], p_selftest(obj)]
    return canon(obj) == DIGESTS["s2:" + name]


def package_sources(workspace: Path) -> str:
    try:
        zf = zipfile.ZipFile(workspace / OUT / "package.zip")
        parts = []
        for n in zf.namelist():
            # Only the package tree under src/ is what runs; notes, outputs and tests beside it are not the package.
            if "src" in Path(n).parts[:-1] and \
                    n.endswith((".py", ".json", ".toml", ".cfg", ".txt", ".csv", ".pkl", ".yaml")):
                parts.append(zf.read(n).decode("utf-8", errors="replace"))
        return "\n".join(parts)
    except (OSError, zipfile.BadZipFile, ValueError):
        return ""


def package_probe(workspace: Path, source: str) -> bool:
    try:
        st = _prepare(workspace)
        return bool(st.get("installed")) and _run(
            [PYTHON, "-S", "-c", source], str(st["tmp"]), st["env"], timeout=30
        ) == 0
    except Exception:
        return False


