# ----------------------------------------------------------------------- package contract checks
def _contract_case(workspace: Path, category: str, index: int) -> bool:
    # rewardkit may evaluate criteria concurrently. Each probe runs under the
    # verifier's untrusted uid and _run deliberately kills that uid's leftover
    # processes, so serialize probes to keep one case from killing another.
    with _CONTRACT_LOCK:
        return _contract_case_serial(workspace, category, index)


def _contract_case_serial(workspace: Path, category: str, index: int) -> bool:
    major, minor, patch = 1 + index % 7, (index * 3) % 11, (index * 5) % 13
    base = f"{major}.{minor}.{patch}"
    if category == "semver_precedence":
        return package_probe(workspace,
            "from trainyard.deps import version_key\n"
            f"assert version_key('{base}+linux.{index}') == version_key('{base}+mac.{index + 1}') == version_key('{base}')\n"
            f"assert version_key('{base}-rc.{index + 1}+one') == version_key('{base}-rc.{index + 1}+two')\n")
    if category == "semver_release_precedence":
        return package_probe(workspace,
            "from trainyard.deps import version_key\n"
            f"assert version_key('{base}+linux.{index}') == version_key('{base}+mac.{index + 1}') == version_key('{base}')\n")
    if category == "semver_prerelease_precedence":
        return package_probe(workspace,
            "from trainyard.deps import version_key\n"
            f"assert version_key('{base}-rc.{index + 1}+one') == version_key('{base}-rc.{index + 1}+two')\n")
    if category == "semver_constraints":
        return package_probe(workspace,
            "from trainyard.deps import satisfies\n"
            f"assert satisfies('{base}+rebuilt.{index}', '={base}')\n"
            f"assert satisfies('{base}-rc.2+rebuilt.{index}', '>={base}-rc.1,<{base}')\n")
    if category == "semver_exact_constraint":
        return package_probe(workspace,
            "from trainyard.deps import satisfies\n"
            f"assert satisfies('{base}+rebuilt.{index}', '={base}')\n")
    if category == "semver_prerelease_range":
        return package_probe(workspace,
            "from trainyard.deps import satisfies\n"
            f"assert satisfies('{base}-rc.2+rebuilt.{index}', '>={base}-rc.1,<{base}')\n")
    if category == "commit_prefix":
        short = f"{index + 1:08x}"
        sha = short + "abcdef0123456789abcdef0123456789"
        old = f"{index + 101:08x}" + "0123456789abcdef0123456789abcdef"
        return package_probe(workspace,
            "from trainyard.feed import Feed\n"
            f"f=Feed.__new__(Feed); f.shas=['{sha}']; f.rewritten={{'{old}':'{sha}'}}\n"
            f"assert f.resolve_commit('{short}') is None\n"
            f"assert f.resolve_commit('{old[:8]}') is None\n")
    if category == "commit_prefix_current":
        short = f"{index + 1:08x}"
        sha = short + "abcdef0123456789abcdef0123456789"
        return package_probe(workspace,
            "from trainyard.feed import Feed\n"
            f"f=Feed.__new__(Feed); f.shas=['{sha}']; f.rewritten={{}}\n"
            f"assert f.resolve_commit('{short}') is None\n")
    if category == "commit_prefix_rewritten":
        sha = f"{index + 1:08x}" + "abcdef0123456789abcdef0123456789"
        old = f"{index + 101:08x}" + "0123456789abcdef0123456789abcdef"
        return package_probe(workspace,
            "from trainyard.feed import Feed\n"
            f"f=Feed.__new__(Feed); f.shas=['{sha}']; f.rewritten={{'{old}':'{sha}'}}\n"
            f"assert f.resolve_commit('{old[:8]}') is None\n")
    if category == "path":
        return package_probe(workspace, f'''
import json, tempfile
from pathlib import Path
from trainyard import readers
from trainyard.feed import Feed, FeedError
root = Path(tempfile.mkdtemp(prefix="ty-path-{index:02d}-"))
feed = root / "feed"; feed.mkdir()
(root / "outside_{index:02d}.dat").write_text("outside")
idx = {{"control":{{"role":"index","file_id":"IDX","records":"2","control":"ix"}},
       "stage":"P","window":{{"start":"2026-01-01T00:00:00Z","end":"2026-01-02T00:00:00Z"}},
       "jobs":[], "files":[
         {{"file_id":"IDX","path":"catalog_{index:02d}","role":"index","format":"json","chain_pos":0}},
         {{"file_id":"D","path":"../outside_{index:02d}.dat","role":"dummy","format":"txt","chain_pos":1}}]}}
(feed / "catalog_{index:02d}").write_text(json.dumps(idx))
readers.read = lambda *a, **k: readers.Doc({{"file_id":"D","records":"0","control":"d"}}, [], {{"records":0}})
Feed._load_registers = lambda self: None
try:
    Feed(feed, {{"run_control":"0"}})
except FeedError:
    pass
else:
    raise AssertionError("escaped index path was read")
''')
    if category == "count":
        declared = index + 1
        return package_probe(workspace, f'''
import json, tempfile
from pathlib import Path
from trainyard import readers
from trainyard.feed import Feed, FeedError
feed = Path(tempfile.mkdtemp(prefix="ty-count-{index:02d}-"))
(feed / "data_{index:02d}").write_text("unused")
idx = {{"control":{{"role":"index","file_id":"IDX","records":"2","control":"ix"}},
       "stage":"P","window":{{"start":"2026-01-01T00:00:00Z","end":"2026-01-02T00:00:00Z"}},
       "jobs":[], "files":[
         {{"file_id":"IDX","path":"catalog_{index:02d}","role":"index","format":"json","chain_pos":0}},
         {{"file_id":"D","path":"data_{index:02d}","role":"dummy","format":"txt","chain_pos":1}}]}}
(feed / "catalog_{index:02d}").write_text(json.dumps(idx))
readers.read = lambda *a, **k: readers.Doc({{"file_id":"D","records":"{declared}","control":"d"}}, [], {{"records":{declared - 1}}})
Feed._load_registers = lambda self: None
try:
    Feed(feed, {{"run_control":"0"}})
except FeedError:
    pass
else:
    raise AssertionError("declared/read mismatch was accepted")
''')
    return False


def _path_contract_case(workspace: Path, kind: str, index: int) -> bool:
    with _CONTRACT_LOCK:
        return _path_contract_case_serial(workspace, kind, index)


def _path_contract_case_serial(workspace: Path, kind: str, index: int) -> bool:
    if kind == "absolute":
        path_setup = f'(root / "outside_{index:02d}.dat").write_text("outside")'
        indexed_path = f'str(root / "outside_{index:02d}.dat")'
    elif kind == "symlink":
        path_setup = (
            f'(root / "outside_{index:02d}.dat").write_text("outside")\n'
            f'(feed / "link_{index:02d}.dat").symlink_to(root / "outside_{index:02d}.dat")'
        )
        indexed_path = f'"link_{index:02d}.dat"'
    else:
        return False
    return package_probe(workspace, f'''
import json, tempfile
from pathlib import Path
from trainyard import readers
from trainyard.feed import Feed, FeedError
root = Path(tempfile.mkdtemp(prefix="ty-path-{kind}-{index:02d}-"))
feed = root / "feed"; feed.mkdir()
{path_setup}
idx = {{"control":{{"role":"index","file_id":"IDX","records":"2","control":"ix"}},
       "stage":"P","window":{{"start":"2026-01-01T00:00:00Z","end":"2026-01-02T00:00:00Z"}},
       "jobs":[], "files":[
         {{"file_id":"IDX","path":"catalog_{index:02d}","role":"index","format":"json","chain_pos":0}},
         {{"file_id":"D","path":{indexed_path},"role":"dummy","format":"txt","chain_pos":1}}]}}
(feed / "catalog_{index:02d}").write_text(json.dumps(idx))
readers.read = lambda *a, **k: readers.Doc({{"file_id":"D","records":"0","control":"d"}}, [], {{"records":0}})
Feed._load_registers = lambda self: None
try:
    Feed(feed, {{"run_control":"0"}})
except FeedError:
    pass
else:
    raise AssertionError("index path escaped the feed directory")
''')


def _index_count_case(workspace: Path, index: int) -> bool:
    with _CONTRACT_LOCK:
        return package_probe(workspace, f'''
import json, tempfile
from pathlib import Path
from trainyard import readers
from trainyard.feed import Feed, FeedError
feed = Path(tempfile.mkdtemp(prefix="ty-index-count-{index:02d}-"))
(feed / "data_{index:02d}").write_text("unused")
idx = {{"control":{{"role":"index","file_id":"IDX","records":"3","control":"ix"}},
       "stage":"P","window":{{"start":"2026-01-01T00:00:00Z","end":"2026-01-02T00:00:00Z"}},
       "jobs":[], "files":[
         {{"file_id":"IDX","path":"catalog_{index:02d}","role":"index","format":"json","chain_pos":0}},
         {{"file_id":"D","path":"data_{index:02d}","role":"dummy","format":"txt","chain_pos":1}}]}}
(feed / "catalog_{index:02d}").write_text(json.dumps(idx))
readers.read = lambda *a, **k: readers.Doc({{"file_id":"D","records":"0","control":"d"}}, [], {{"records":0}})
Feed._load_registers = lambda self: None
try:
    Feed(feed, {{"run_control":"0"}})
except FeedError:
    pass
else:
    raise AssertionError("index declared record count mismatch was accepted")
''')


