# ----------------------------------------------------------------------- outcome-level scoring checks
@_legacy_criterion(description="package.zip has the required installable src layout and preserves the shipped passing test suite")
def package_archive_is_viable(workspace: Path) -> bool:
    checks = (package_archive_layout, package_installs_and_imports, package_shipped_tests_pass)
    return all(check(workspace) for check in checks)


@criterion(description="the repaired package produces the exact complete stage-1 ledger")
def stage1_ledger_is_exact(workspace: Path) -> bool:
    checks = (
        stage1_outputs_stamped,
        selftest_control_chain,
        build_report_membership,
        build_report_module_identity,
        build_report_time_and_scope,
        build_report_units_and_sentinels,
        build_report_attempt_precedence,
        build_report_crash_buckets,
        build_report_commits,
        build_report_row_order,
        ledger_field_sets,
        module_core_states,
        module_core_bisection,
        module_core_dominant_bucket,
        module_metrics_counts_and_rates,
        module_metrics_flaky_and_quarantine,
        module_metrics_median,
        dependency_resolution_constraints,
        dependency_resolution_semver,
        summary_totals,
        summary_last_good,
        summary_open_flaky,
        summary_seen_build_keys,
    )
    return all(check(workspace) for check in checks)


@criterion(description="the repaired package produces the exact complete ledger for the renamed later-stage feed")
def stage2_ledger_is_exact(workspace: Path) -> bool:
    checks = (
        stage2_selftest,
        stage2_build_report,
        stage2_module_core,
        stage2_module_metrics,
        stage2_dependency_resolution,
        stage2_summary,
    )
    return all(check(workspace) for check in checks)


