# ----------------------------------------------------------------------- negative checks
@criterion(description="the package carries stage-1 answers as literals")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # True when the cheat happened; the negative weight does the punishing.
    try:
        text = package_sources(workspace)
        if not text:
            return False
        if S1_STAMP["run_control"] in text:
            return True
        return sum(1 for k in S1_KEY_PROBE if k in text) >= 20
    except Exception:
        return False


@criterion(description="two runs of the package on the same input produce different bytes")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # True when the cheat happened; the negative weight does the punishing.
    try:
        st = _prepare(workspace)
        a, b = st["runs"].get("plain"), st["runs"].get("again")
        if not a or not b or all(v is None for v in a[1].values()):
            return False
        return a[1] != b[1]
    except Exception:
        return False


